#ifndef EIRON2_SOURCE_HPP
#define EIRON2_SOURCE_HPP

#include "eiron2/common/utils.hpp"
#include "eiron2/common/vec2.hpp"
#include "eiron2/physics/particle.hpp"

namespace eiron2 {

/**
 * @brief An abstract class to represent a source of particles
 *
 */
class Source {
   public:
    Source() : max_particles_(0) {}
    Source(index_t max_particles) : max_particles_(max_particles) {}

    ~Source() = default;

    /**
     * @brief Return the number of particles that will be generated by this
     * source
     */
    index_t max_particles() const;

    /**
     * @brief Return the number of particles are left to generate
     *        from this source
     */
    index_t particles_left() const;

    /**
     * Generate a particle from this source
     *
     * @param p
     */
    virtual Particle generate_particle() = 0;

    index_t max_particles_;  // the number of particles to generate from this source
    index_t i_particle = 0;  // the number of particles that have been generated
    index_t particle_id_offset = 0;  // the offset to add to the particle id
};

}  // namespace eiron2

#endif